'use strict';
// The same complete-menu view is used for every store.
function drinkTags(d){const values=TeaMenu.itemTags(d),brand=brands.find(b=>b.name===d.brand),top=brand?.topPicks,selected=top?.enabled===true&&top.itemIds?.includes(d.id);if(!selected)return values;return ['必喝 TOP',...values.filter(value=>value!=='推薦'&&value!=='必喝 TOP')];}
function tagGroup(values,cls='quick-menu-tags'){const host=el('span',undefined,cls);for(const value of values){const tagClass=value==='推薦'||value==='必喝 TOP'?'quick-menu-recommend quick-menu-recommendation':'quick-menu-recommend';host.append(el('span',value,tagClass));}return host;}
function quickMenuPrice(d){const sizes=[...new Set(d.variants.map(v=>v.size))];return sizes.map(size=>{const variants=d.variants.filter(v=>v.size===size),seen=new Set(),parts=[];for(const v of variants){const key=String(v.price);if(seen.has(key))continue;seen.add(key);parts.push(v.price===null?'價格待確認':`$${v.price}`);}return `${size.replace('杯','')} ${parts.join('／')}`;}).join('　');}
function completeMenuState(state){return {...state,temp:'',size:'',cal:'',price:'',oat:false,largeWarm:false,unknown:false,sort:'default'};}
function renderQuickMenu(){const holder=$('quick-menu');holder.hidden=!s.brand;if(holder.hidden){if(typeof placeMenuSearch==='function')placeMenuSearch(null);return;}if(!holder.menuParts){const heading=el('div',undefined,'menu-heading-slot'),search=el('div',undefined,'menu-search-slot'),body=el('div',undefined,'menu-body-slot');holder.menuParts={heading,search,body};holder.append(heading,search,body);}const parts=holder.menuParts;parts.body.replaceChildren();if(typeof placeMenuSearch==='function')placeMenuSearch(parts.search);const brand=brands.find(b=>b.name===s.brand);const availableRegions=Array.isArray(brand?.regions)?brand.regions.filter(r=>r.enabled!==false):[];if(availableRegions.length){const current=availableRegions.some(r=>r.id===s.regions[0])?s.regions[0]:availableRegions[0].id;if(s.regions.length!==1||s.regions[0]!==current){s.regions=[current];sync();}}const items=query(completeMenuState(s)).yes.filter(d=>d.brand===s.brand);const heading=el('div',undefined,'quick-menu-heading'),titleBox=el('div','', 'quick-menu-intro');const title=el('h2',brand.name+' Menu');title.id='quick-menu-title';titleBox.append(title);const actions=el('div',undefined,'quick-menu-heading-actions'),brandTags=Array.isArray(brand.tags)?brand.tags:[];if(brandTags.length)actions.append(tagGroup(brandTags,'quick-menu-store-tags'));heading.append(titleBox,actions);parts.heading.replaceChildren(heading);
if(availableRegions.length>1){const regions=el('div',undefined,'quick-menu-regions');regions.setAttribute('role','radiogroup');regions.setAttribute('aria-label','地區菜單');regions.append(el('span','地區菜單'));for(const region of availableRegions){const selected=s.regions[0]===region.id;const button=btn(region.name,()=>{s.regions=[region.id];sync();render();});button.setAttribute('role','radio');button.setAttribute('aria-checked',String(selected));button.setAttribute('aria-pressed',String(selected));regions.append(button);}parts.body.append(regions);}
const nav=el('nav',undefined,'quick-menu-nav');nav.setAttribute('aria-label',brand.name+'菜單分類，可複選');const all=btn('全部',()=>{s.cats=[];sync();render();});all.setAttribute('aria-pressed',String(!s.cats.length));nav.append(all);for(const category of brand.menus){const b=btn(brand.categoryLabels?.[category]||category,()=>{s.cats=s.cats.includes(category)?s.cats.filter(c=>c!==category):[...s.cats,category];sync();render();});b.setAttribute('aria-pressed',String(s.cats.includes(category)));nav.append(b);}parts.body.append(nav);
if(!items.length){const empty=el('div',undefined,'quick-menu-empty');empty.append(el('h3','這組條件暫時找不到飲料'),el('p','可以換個關鍵字或切換其他菜單分類。'));parts.body.append(empty);return;}
const grid=el('div',undefined,'quick-menu-grid'),categories=[...brand.menus,...items.map(d=>d.menuCategory)];for(const category of [...new Set(categories)]){const members=items.filter(d=>d.menuCategory===category);if(!members.length)continue;const group=el('section',undefined,'quick-menu-group'),groupHead=el('div',undefined,'quick-menu-group-heading');groupHead.append(el('h3',brand.categoryLabels?.[category]||category));const categoryTags=brand.categoryTags?.[category]||[];if(categoryTags.length)groupHead.append(tagGroup(categoryTags,'quick-menu-category-tags'));group.append(groupHead);for(const d of members){const row=el('div',undefined,'quick-menu-row');row.id='menu-item-'+d.id;const detail=btn('',()=>openOrder(d.id),'quick-menu-detail'),name=el('span',undefined,'quick-menu-name'),nameLine=el('span',undefined,'quick-menu-name-line'),nameText=el('strong',d.name);nameLine.append(nameText);const tags=drinkTags(d);if(tags.length)nameLine.append(tagGroup(tags));name.append(nameLine);if(d.note)name.append(el('small',d.note,'quick-menu-note'));const meta=el('span',quickMenuPrice(d),'quick-menu-price'),hint=el('span','詳細','quick-menu-hint');detail.setAttribute('aria-label',`開啟 ${d.name} 的詳細設定`);detail.append(name,meta,hint);const copy=btn('複製',()=>copyName(d.name),'quick-menu-copy');copy.setAttribute('aria-label',`複製 ${d.name} 品名`);row.append(detail,copy);group.append(row);}grid.append(group);}parts.body.append(grid);}
